func NkIsInline(kind int32) int32 {
	// 1 for the kinds that live inside a block's text: text, span, link,
	// ref, linebreak, initial (SPEC 3.2). A `break` is a milestone, not an
	// inline.
	if kind == NkText() {
		return 1
	}
	if kind == NkSpan() {
		return 1
	}
	if kind == NkLink() {
		return 1
	}
	if kind == NkRef() {
		return 1
	}
	if kind == NkLinebreak() {
		return 1
	}
	if kind == NkInitial() {
		return 1
	}
	return 0
}

func NodeIsInline(nodes *port.Cells, n int32) int32 {
	// 1 when node n is an inline: an inline KIND, or a `break` with an inline neighbour (D134). A page
	// milestone INSIDE a paragraph (text, break, text) is an inline -- written in `inlines`, in order,
	// with no `id` -- and BETWEEN two blocks it is a block, as `nk-is-inline` of its kind says.
	var kind int32 = nget(nodes, n, 0)
	var pv int32 = nget(nodes, n, 5)
	var nx int32 = nget(nodes, n, 4)
	if NkIsInline(kind) == 1 {
		return 1
	}
	if kind == NkBreak() {
		if pv >= 0 {
			var pkind int32 = nget(nodes, pv, 0)
			if NkIsInline(pkind) == 1 {
				return 1
			}
		}
		if nx >= 0 {
			var nkind int32 = nget(nodes, nx, 0)
			if NkIsInline(nkind) == 1 {
				return 1
			}
		}
	}
	return 0
}

func NodeChildCount(nodes *port.Cells, n int32) int32 {
	var c int32 = nget(nodes, n, 2)
	var k int32 = 0
	for c >= 0 {
		k += 1
		c = nget(nodes, c, 4)
	}
	return k
}

func NodeDepth(nodes *port.Cells, n int32) int32 {
	// Edges from the node to its root: the root is 0.
	var p int32 = nget(nodes, n, 1)
	var d int32 = 0
	for p >= 0 {
		d += 1
		p = nget(nodes, p, 1)
	}
	return d
}

func NodeNew(nodes *port.Cells, kind int32, parent int32) int32 {
	// Append a node as the LAST child of `parent` (-1: a new root) and
	// answer its index, or -1 when `parent` is not a node, the kind is
	// unknown, or the node would nest deeper than `max-depth`. A new
	// node has no text, no regions, no attributes, `src` 0, `conf` -1
	// (absent), `flags` 0, `sub` 0, `aux` 0.
	var n int32 = port.CellsLen(nodes) / 16
	var last int32 = -1
	if (kind < 1) || (kind > 26) {
		return -1
	}
	if parent < -1 {
		return -1
	}
	if parent >= n {
		return -1
	}
	if parent >= 0 {
		if NodeDepth(nodes, parent) >= (MaxDepth() - 1) {
			return -1
		}
		last = nget(nodes, parent, 3)
	}
	port.CellsPush(nodes, kind)
	port.CellsPush(nodes, parent)
	port.CellsPush(nodes, -1)
	port.CellsPush(nodes, -1)
	port.CellsPush(nodes, -1)
	port.CellsPush(nodes, last)
	port.CellsPush(nodes, -1)
	port.CellsPush(nodes, -1)
	port.CellsPush(nodes, 0)
	port.CellsPush(nodes, -1)
	port.CellsPush(nodes, 0)
	port.CellsPush(nodes, 0)
	port.CellsPush(nodes, -1)
	port.CellsPush(nodes, 0)
	port.CellsPush(nodes, 0)
	port.CellsPush(nodes, 0)
	if parent >= 0 {
		if last < 0 {
			nput(nodes, parent, 2, n)
		} else {
			nput(nodes, last, 4, n)
		}
		nput(nodes, parent, 3, n)
	}
	return n
}

func ModelInit(nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, pages *port.Cells, ledger *port.Cells, layout *port.Cells) int32 {
	// Empty all seven arenas and create the `document` root, node 0.
	port.CellsDrop(nodes, 0)
	port.CellsDrop(attrs, 0)
	port.CellsDrop(regions, 0)
	port.CellsDrop(text, 0)
	port.CellsDrop(pages, 0)
	port.CellsDrop(ledger, 0)
	port.CellsDrop(layout, 0)
	NodeNew(nodes, NkDocument(), -1)
	return 0
}

