func TextAppendCp(text *port.Cells, cp int32) int32 {
	// Append one Unicode scalar value; answer the index it went to.
	// Anything that is not a scalar value (negative, past U+10FFFF, a
	// surrogate) is stored as U+FFFD, so the arena only ever holds
	// what SPEC 3.6 says it holds.
	if cp < 0 {
		return port.CellsPush(text, 65533)
	}
	if cp > 1114111 {
		return port.CellsPush(text, 65533)
	}
	if (cp >= 55296) && (cp <= 57343) {
		return port.CellsPush(text, 65533)
	}
	return port.CellsPush(text, cp)
}

func TextAppendUtf8(text *port.Cells, b []byte, from int32, to int32) int32 {
	// Decode b[from, to) as UTF-8 onto the text arena; answer the number
	// of code points appended. Invalid input becomes U+FFFD (SPEC 4.3:
	// 'invalid input decodes to U+FFFD at the source'), ONE per maximal
	// invalid subpart: a stray continuation byte, a bad lead, or a
	// sequence cut short is a single replacement, and decoding resumes
	// at the first byte that was not part of it.
	var i int32 = from
	var k int32 = 0
	var c int32 = 0
	var cp int32 = 0
	var need int32 = 0
	var lo int32 = 128
	var hi int32 = 191
	var ok int32 = 1
	var x int32 = 0
	for i < to {
		c = port.BlobU8(b, i)
		i += 1
		need = 0
		lo = 128
		hi = 191
		ok = 1
		cp = c
		if c >= 128 {
			ok = 0
			if (c >= 194) && (c <= 223) {
				need = 1
				cp = c & 31
				ok = 1
			}
			if (c >= 224) && (c <= 239) {
				need = 2
				cp = c & 15
				ok = 1
				if c == 224 {
					lo = 160
				}
				if c == 237 {
					hi = 159
				}
			}
			if (c >= 240) && (c <= 244) {
				need = 3
				cp = c & 7
				ok = 1
				if c == 240 {
					lo = 144
				}
				if c == 244 {
					hi = 143
				}
			}
		}
		for (ok == 1) && (need > 0) {
			if i < to {
				x = port.BlobU8(b, i)
				if (x >= lo) && (x <= hi) {
					cp = (cp * 64) + (x & 63)
					i += 1
					need -= 1
					lo = 128
					hi = 191
				} else {
					ok = 0
				}
			} else {
				ok = 0
			}
		}
		if ok == 0 {
			cp = 65533
		}
		TextAppendCp(text, cp)
		k += 1
	}
	return k
}

func NodeAddRegion(nodes *port.Cells, regions *port.Cells, n int32, page int32, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// Append a region to the node's chain (in the order added: a node
	// spanning pages has one region per page, in page order) and answer
	// the region's index.
	var r int32 = port.CellsLen(regions) / 6
	var cnt int32 = nget(nodes, n, 10)
	var t int32 = nget(nodes, n, 9)
	port.CellsPush(regions, page)
	port.CellsPush(regions, x0)
	port.CellsPush(regions, y0)
	port.CellsPush(regions, x1)
	port.CellsPush(regions, y1)
	port.CellsPush(regions, -1)
	if cnt == 0 {
		nput(nodes, n, 9, r)
	} else {
		for port.CellsAt(regions, (t*6)+5) >= 0 {
			t = port.CellsAt(regions, (t*6)+5)
		}
		port.CellsSet(regions, (t*6)+5, r)
	}
	nput(nodes, n, 10, cnt+1)
	return r
}

