func AttrFind(attrs *port.Cells, head int32, key int32) int32 {
	// The first attribute with `key` in the chain from `head`, or -1.
	var a int32 = head
	for a >= 0 {
		if aget(attrs, a, 0) == key {
			return a
		}
		a = aget(attrs, a, 4)
	}
	return -1
}

func AttrFindNext(attrs *port.Cells, a int32, key int32) int32 {
	// The next attribute with `key` AFTER a (a key may repeat: a
	// figure's `labels`, a furniture's `pages`), or -1.
	var nx int32 = aget(attrs, a, 4)
	return AttrFind(attrs, nx, key)
}

func NodeAttr(nodes *port.Cells, attrs *port.Cells, n int32, key int32) int32 {
	// The node's first attribute with `key`, or -1.
	return AttrFind(attrs, nget(nodes, n, 6), key)
}

func NodeAttrIntOr(nodes *port.Cells, attrs *port.Cells, n int32, key int32, dflt int32) int32 {
	// An int, bool or node attribute's value, or `dflt` when absent.
	var a int32 = AttrFind(attrs, nget(nodes, n, 6), key)
	if a < 0 {
		return dflt
	}
	return aget(attrs, a, 2)
}

func attrPut(nodes *port.Cells, attrs *port.Cells, n int32, key int32, vkind int32, value int32, ln int32, replace int32) int32 {
	// Set (replace = 1: overwrite the first attribute with the key, if
	// there is one) or add (replace = 0: always append) an attribute.
	var head int32 = nget(nodes, n, 6)
	var found int32 = AttrFind(attrs, head, key)
	var a int32 = port.CellsLen(attrs) / 5
	var t int32 = head
	if (replace == 1) && (found >= 0) {
		port.CellsSet(attrs, (found*5)+1, vkind)
		port.CellsSet(attrs, (found*5)+2, value)
		port.CellsSet(attrs, (found*5)+3, ln)
		return found
	}
	port.CellsPush(attrs, key)
	port.CellsPush(attrs, vkind)
	port.CellsPush(attrs, value)
	port.CellsPush(attrs, ln)
	port.CellsPush(attrs, -1)
	if head < 0 {
		nput(nodes, n, 6, a)
	} else {
		for port.CellsAt(attrs, (t*5)+4) >= 0 {
			t = port.CellsAt(attrs, (t*5)+4)
		}
		port.CellsSet(attrs, (t*5)+4, a)
	}
	return a
}

func NodeSetAttrInt(nodes *port.Cells, attrs *port.Cells, n int32, key int32, v int32) int32 {
	return attrPut(nodes, attrs, n, key, 0, v, 0, 1)
}

func NodeSetAttrBool(nodes *port.Cells, attrs *port.Cells, n int32, key int32, v int32) int32 {
	// Any non-zero v is stored as 1.
	if v != 0 {
		return attrPut(nodes, attrs, n, key, 3, 1, 0, 1)
	}
	return attrPut(nodes, attrs, n, key, 3, 0, 0, 1)
}

func NodeSetAttrNode(nodes *port.Cells, attrs *port.Cells, n int32, key int32, target int32) int32 {
	return attrPut(nodes, attrs, n, key, 2, target, 0, 1)
}

func NodeSetAttrText(nodes *port.Cells, attrs *port.Cells, n int32, key int32, start int32, ln int32) int32 {
	// The value is the run [start, start+length) of the text arena.
	return attrPut(nodes, attrs, n, key, 1, start, ln, 1)
}

func NodeSetAlign(nodes *port.Cells, attrs *port.Cells, n int32, v int32) int32 {
	// Set the alignment of a paragraph (its `sub`), heading, caption or cell
	// (the attribute `fk-align`), a logical `al` code (D110). Answers 0, or -1
	// when the value is not an `al` code, the node is not one of those kinds,
	// or it is a cell and the value is `justify`.
	var kind int32 = nget(nodes, n, 0)
	if (v < 1) || (v > 4) {
		return -1
	}
	if kind == NkParagraph() {
		nput(nodes, n, 14, v)
		return 0
	}
	if (kind == NkCell()) && (v == AlJustify()) {
		return -1
	}
	if (kind == NkHeading()) || (kind == NkCaption()) || (kind == NkCell()) {
		attrPut(nodes, attrs, n, FkAlign(), 0, v, 0, 1)
		return 0
	}
	return -1
}

func NodeAddAttrInt(nodes *port.Cells, attrs *port.Cells, n int32, key int32, v int32) int32 {
	// Append, even if the key is already there (a repeated key).
	return attrPut(nodes, attrs, n, key, 0, v, 0, 0)
}

func NodeAddAttrText(nodes *port.Cells, attrs *port.Cells, n int32, key int32, start int32, ln int32) int32 {
	return attrPut(nodes, attrs, n, key, 1, start, ln, 0)
}

func PageNew(pages *port.Cells, number int32, w int32, h int32, rot int32, kind int32) int32 {
	// Append a page-table row and answer its index. A new row has no
	// label, no health and no resolution.
	var p int32 = port.CellsLen(pages) / 16
	var i int32 = 0
	port.CellsPush(pages, number)
	port.CellsPush(pages, -1)
	port.CellsPush(pages, 0)
	port.CellsPush(pages, w)
	port.CellsPush(pages, h)
	port.CellsPush(pages, rot)
	port.CellsPush(pages, kind)
	port.CellsPush(pages, -1)
	port.CellsPush(pages, 0)
	port.CellsPush(pages, 0)
	port.CellsPush(pages, 0)
	for i < 5 {
		port.CellsPush(pages, 0)
		i += 1
	}
	return p
}

