func mcFail(st *port.Cells, code int32, at int32) int32 {
	port.CellsSet(st, 0, at)
	return code
}

func mcLinkOk(v int32, n int32) int32 {
	// 1 when v is -1 or an index below n.
	if v < -1 {
		return 0
	}
	if v >= n {
		return 0
	}
	return 1
}

func mcRunOk(start int32, ln int32, tl int32) int32 {
	// 1 for an absent run (start -1, ln 0) or one inside [0, tl).
	if start == -1 {
		if ln == 0 {
			return 1
		}
		return 0
	}
	if start < 0 {
		return 0
	}
	if ln < 0 {
		return 0
	}
	if start > tl {
		return 0
	}
	if ln > (tl - start) {
		return 0
	}
	return 1
}

func mcCheckNode(nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, n int32, nn int32) int32 {
	// One node's own fields. 0 or an `mc` code.
	var kind int32 = nget(nodes, n, 0)
	var cnt int32 = nget(nodes, n, 10)
	var conf int32 = nget(nodes, n, 12)
	var a int32 = nget(nodes, n, 6)
	var r int32 = nget(nodes, n, 9)
	var steps int32 = 0
	var na int32 = port.CellsLen(attrs) / 5
	var nr int32 = port.CellsLen(regions) / 6
	var tl int32 = port.CellsLen(text)
	if (kind < 1) || (kind > 26) {
		return McBadKind()
	}
	if mcLinkOk(nget(nodes, n, 1), nn) == 0 {
		return McBadLink()
	}
	if mcLinkOk(nget(nodes, n, 2), nn) == 0 {
		return McBadLink()
	}
	if mcLinkOk(nget(nodes, n, 3), nn) == 0 {
		return McBadLink()
	}
	if mcLinkOk(nget(nodes, n, 4), nn) == 0 {
		return McBadLink()
	}
	if mcLinkOk(nget(nodes, n, 5), nn) == 0 {
		return McBadLink()
	}
	if mcRunOk(nget(nodes, n, 7), nget(nodes, n, 8), tl) == 0 {
		return McBadText()
	}
	if (conf < -1) || (conf > 1000) {
		return McBadConf()
	}
	for a >= 0 {
		if a >= na {
			return McBadAttr()
		}
		if steps > na {
			return McBadAttr()
		}
		steps += 1
		if aget(attrs, a, 1) == 1 {
			if mcRunOk(aget(attrs, a, 2), aget(attrs, a, 3), tl) == 0 {
				return McBadAttr()
			}
		}
		if mcLinkOk(aget(attrs, a, 4), na) == 0 {
			return McBadAttr()
		}
		if (aget(attrs, a, 1) < 0) || (aget(attrs, a, 1) > 3) {
			return McBadAttr()
		}
		a = aget(attrs, a, 4)
	}
	steps = 0
	for r >= 0 {
		if r >= nr {
			return McBadRegion()
		}
		if steps > nr {
			return McBadRegion()
		}
		steps += 1
		if mcLinkOk(rget(regions, r, 5), nr) == 0 {
			return McBadRegion()
		}
		r = rget(regions, r, 5)
	}
	if steps != cnt {
		return McBadRegion()
	}
	return 0
}

func mcCheckChildren(nodes *port.Cells, n int32, nn int32) int32 {
	// The child chain of n: every child points back at n, prev links
	// agree, `last-child` is the end of the chain. Answers the number of
	// children, or -1 when the chain is wrong.
	var c int32 = nget(nodes, n, 2)
	var prev int32 = -1
	var k int32 = 0
	for c >= 0 {
		if k > nn {
			return -1
		}
		if nget(nodes, c, 1) != n {
			return -1
		}
		if nget(nodes, c, 5) != prev {
			return -1
		}
		k += 1
		prev = c
		c = nget(nodes, c, 4)
	}
	if nget(nodes, n, 3) != prev {
		return -1
	}
	return k
}

func mcCheckOrder(nodes *port.Cells, nn int32, st *port.Cells) int32 {
	// Pre-order ids: walking each tree in pre-order, from its root,
	// visits the indices consecutively, and the trees follow each other
	// in index order. So an id is the node's position in document
	// order (SPEC 3.3).
	var i int32 = 0
	var expect int32 = 0
	var cur int32 = 0
	for i < nn {
		if nget(nodes, i, 1) == -1 {
			if i != expect {
				return mcFail(st, McNotPreorder(), i)
			}
			cur = i
			for cur >= 0 {
				if cur != expect {
					return mcFail(st, McNotPreorder(), cur)
				}
				expect += 1
				if nget(nodes, cur, 2) >= 0 {
					cur = nget(nodes, cur, 2)
				} else {
					for (cur >= 0) && (cur != i) && (nget(nodes, cur, 4) < 0) {
						cur = nget(nodes, cur, 1)
					}
					if cur == i {
						cur = -1
					} else if cur >= 0 {
						cur = nget(nodes, cur, 4)
					}
				}
			}
		}
		i += 1
	}
	if expect != nn {
		return mcFail(st, McNotPreorder(), expect)
	}
	return 0
}

func ModelCheck(nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, pages *port.Cells, ledger *port.Cells, layout *port.Cells, st *port.Cells) int32 {
	var nn int32 = port.CellsLen(nodes) / 16
	var nlay int32 = port.CellsLen(layout) / 8
	var j int32 = 0
	var i int32 = 0
	var rc int32 = 0
	var kids int32 = 0
	var total int32 = 0
	var nonroot int32 = 0
	var tl int32 = port.CellsLen(text)
	port.CellsDrop(st, 0)
	port.CellsPush(st, 0)
	if (port.CellsLen(nodes) % 16) != 0 {
		return mcFail(st, McBadStride(), 0)
	}
	if (port.CellsLen(attrs) % 5) != 0 {
		return mcFail(st, McBadStride(), 0)
	}
	if (port.CellsLen(regions) % 6) != 0 {
		return mcFail(st, McBadStride(), 0)
	}
	if (port.CellsLen(pages) % 16) != 0 {
		return mcFail(st, McBadStride(), 0)
	}
	if (port.CellsLen(ledger) % 10) != 0 {
		return mcFail(st, McBadStride(), 0)
	}
	if (port.CellsLen(layout) % 8) != 0 {
		return mcFail(st, McBadStride(), 0)
	}
	if nn < 1 {
		return mcFail(st, McNoRoot(), 0)
	}
	if nget(nodes, 0, 0) != NkDocument() {
		return mcFail(st, McNoRoot(), 0)
	}
	if nget(nodes, 0, 1) != -1 {
		return mcFail(st, McNoRoot(), 0)
	}
	for i < nn {
		rc = mcCheckNode(nodes, attrs, regions, text, i, nn)
		if rc != 0 {
			return mcFail(st, rc, i)
		}
		i += 1
	}
	i = 0
	for i < nn {
		kids = mcCheckChildren(nodes, i, nn)
		if kids < 0 {
			return mcFail(st, McBadTree(), i)
		}
		total += kids
		if nget(nodes, i, 1) >= 0 {
			nonroot += 1
		}
		i += 1
	}
	if total != nonroot {
		return mcFail(st, McBadTree(), 0)
	}
	rc = mcCheckOrder(nodes, nn, st)
	if rc != 0 {
		return rc
	}
	i = 0
	for i < (port.CellsLen(pages) / 16) {
		if mcRunOk(pget(pages, i, 1), pget(pages, i, 2), tl) == 0 {
			return mcFail(st, McBadPage(), i)
		}
		i += 1
	}
	i = 0
	for i < (port.CellsLen(ledger) / 10) {
		if mcRunOk(lget(ledger, i, 6), lget(ledger, i, 7), tl) == 0 {
			return mcFail(st, McBadLedger(), i)
		}
		if (lget(ledger, i, 8) < -1) || (lget(ledger, i, 8) > 1000) {
			return mcFail(st, McBadLedger(), i)
		}
		i += 1
	}
	i = 0
	for i < (port.CellsLen(pages) / 16) {
		if pget(pages, i, 12) < 0 {
			return mcFail(st, McBadLayout(), i)
		}
		if pget(pages, i, 12) > 0 {
			if pget(pages, i, 11) < 0 {
				return mcFail(st, McBadLayout(), i)
			}
			if pget(pages, i, 11) > (nlay - pget(pages, i, 12)) {
				return mcFail(st, McBadLayout(), i)
			}
			j = 0
			for j < pget(pages, i, 12) {
				if yget(layout, pget(pages, i, 11)+j, 0) != pget(pages, i, 0) {
					return mcFail(st, McBadLayout(), i)
				}
				if (yget(layout, pget(pages, i, 11)+j, 3) != RlBody()) && (yget(layout, pget(pages, i, 11)+j, 3) != RlMargin()) && (yget(layout, pget(pages, i, 11)+j, 3) != RlSidebar()) {
					return mcFail(st, McBadLayout(), i)
				}
				j += 1
			}
		}
		i += 1
	}
	return 0
}

func mhFold(h int64, c *port.Cells) int64 {
	// FNV-1a over the cells of one arena, each as a 32-bit pattern, then
	// the arena's length -- so two arenas that differ only in where one
	// ends and the next begins do not collide.
	var i int32 = 0
	var acc int64 = h
	for i < port.CellsLen(c) {
		acc = (acc ^ int64(port.CellsAt(c, i))) * 1099511628211
		i += 1
	}
	return (acc ^ int64(port.CellsLen(c))) * 1099511628211
}

func ModelHash(nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, pages *port.Cells, ledger *port.Cells, layout *port.Cells) int64 {
	// A 64-bit fingerprint of the whole Model: the gate's proof that four
	// targets built the same seven arenas. FNV-1a, offset basis
	// 14695981039346656037 (as a signed value) and prime 1099511628211.
	var h int64 = -3750763034362895579
	h = mhFold(h, nodes)
	h = mhFold(h, attrs)
	h = mhFold(h, regions)
	h = mhFold(h, text)
	h = mhFold(h, pages)
	h = mhFold(h, ledger)
	h = mhFold(h, layout)
	return h
}
